import type {
  MedusaRequest,
  MedusaResponse,
} from "@medusajs/framework/http"
import { batchVariantImagesWorkflow } from "@medusajs/medusa/core-flows"

export async function POST(
  req: MedusaRequest,
  res: MedusaResponse
) {
  const { result } = await batchVariantImagesWorkflow(req.scope)
    .run({
      input: {
        variant_id: "variant_123",
        add: ["img_123", "img_456"],
        remove: ["img_789"]
      }
    })

  res.send(result)
}

